  mask-image: linear-gradient(to bottom, transparent 0%, black 22%, black 68%, transparent 100%);
  -webkit-mask-image: linear-gradient(to bottom, transparent 0%, black 22%, black 68%, transparent 100%);
  margin-bottom: 4px;
}

.lyric-list {
  display: flex;
  flex-direction: column;
  gap: 10px;
  transition: transform 0.6s cubic-bezier(0.4, 0, 0.2, 1);
}

/* 歌词居中，未激活为灰色 */
.lyric-line {
  font-size: 11px;
  color: #bbbbbb;
  line-height: 1.55;
  transition: color 0.4s, font-size 0.3s, font-weight 0.3s;
  text-align: center;
}

/* 当前播放行：黑色 */
.lyric-line.active {
  color: #1a1a1a;
  font-size: 12px;
  font-weight: 600;
}

/* 进度栏：自动下沉到底部 */
.progress-wrap {
  position: relative;
  z-index: 2;
  display: flex;
  align-items: center;
  gap: 1px;
  flex-shrink: 0;
  margin-top: auto;
  margin-bottom: 0px;
}

.time {
  font-size: 9px;
  color: #999999;
  min-width: 22px;
}

.time.right {
  text-align: right;
}

.progress-bar {
  flex: 1;
  height: 1.5px;
  background: #cccccc;
  border-radius: 2px;
  cursor: pointer;
}

.progress-fill {
  height: 100%;
  background: #1a1a1a;
  border-radius: 2px;
  width: 0%;
  transition: width 0.5s linear;
}

/* 控制按钮 */
.controls {
  position: relative;
  z-index: 2;
  display: flex;
  justify-content: center;
  gap: 6px;
  flex-shrink: 0;
}

.btn {
  width: 30px;
  height: 30px;
  border-radius: 50%;
  background: rgba(0, 0, 0, 0.06);
  border: none;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: transform 0.15s;
}

.btn:active {
  transform: scale(0.9);
}

.btn svg {
  width: 18px;
  height: 18px;
  fill: #aaaaaa;
  transition: fill 0.25s;
}

/* 收藏点亮：黑色 */
.btn.lit svg {
  fill: #1a1a1a;
}

/* 点赞点亮：偏粉玫瑰红 */
.btn.lit-pink svg {
  fill: #e8718a;
}

