  text-align: center; white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
}

.camera-btn, .plus-btn {
  width: clamp(20px, 5vw, 26px); height: clamp(20px, 5vw, 26px); flex-shrink: 0;
