.plus-btn::before, .plus-btn::after {
  content: ''; position: absolute; background-color: var(--text-sub);
  top: 50%; left: 50%; transform: translate(-50%, -50%); border-radius: 1px;
}
.plus-btn::before { width: 10px; height: 1.5px; } 
