/* 对方气泡弧形尾巴 */
.bubble-them-custom::before {
    content: '' !important;
    position: absolute !important;
    left: -15px !important;
    top: -16px !important;
    width: 50px !important;
    height: 50px !important;
    background-color: #e1e3e6 !important; /* 强制跟气泡同色 */
    -webkit-mask-image: url("https://i.postimg.cc/kMWBZKKX/IMG-1862.png") !important;
    mask-image: url("https://i.postimg.cc/kMWBZKKX/IMG-1862.png") !important;
    -webkit-mask-size: contain !important;
