  --bubble-them-font-size: 15px;
  --bubble-them-line-height: 1.4;
  --bubble-them-padding: 6px 10px;
  --bubble-them-radius: 16px !important;
  --bubble-them-radius-first: 16px 16px 16px 4px;
  --bubble-them-radius-mid: 4px 16px 16px 4px;
  --bubble-them-radius-last: 4px 16px 16px 16px;
  --bubble-them-shadow: 0 4px 12px rgba(0, 0, 0, 0.3); /* 黑色柔光 */
  --bubble-them-border: none !important;
  --bubble-them-link-color: #F0F0F0;
  --bubble-them-backdrop: blur(8px) saturate(150%);

  /* === 翻译内容 === */
  --translation-btn-color: #1A3E4C;
  --translation-text-color: #1A3E4C;
