  --quote-border-color: rgba(107, 114, 128, 0.45);
  --quote-text-color: #6b7280;
  --code-bg: rgba(107, 114, 128, 0.12);
  --code-color: #6b7280;
  --reply-block-bg: rgba(0, 0, 0, 0.06);
