    background-image: url('https://img.baibai.cv/f/QqOeTa/1000036714.png') !important;
    background-size: contain !important;
    background-repeat: no-repeat !important;
    background-position: center !important;
    background-color: transparent !important;
    border: none !important;
    font-size: 0 !important;
    color: transparent !important;
    text-indent: -9999px !important;
    overflow: hidden !important;
    width: 25px !important;
    height: 25px !important;
}

/* ===== 章节导航按钮（上一张/下一张）：灰色背景，白色文字 ===== */
.nook-page-nav button,
.nook-page-nav .nook-icon-btn {
    background: #808080 !important;
    color: #ffffff !important;
    border: none !important;
    box-shadow: none !important;
}

/* ===== 翻页页码：取消背景，文字黑灰色，无边框 ===== */
.nook-flip-ind {
    background: transparent !important;
    color: #333333 !important;
    border: none !important;
}

/* ===== 强制覆盖所有高亮/荧光类背景为 #a2a1a4 并带 65% 透明度 ===== */
.nook-reader-page .nook-hl,
.nook-reader-page .nook-hl-user,
.nook-reader-page .nook-scribble,
.nook-reader-page .nook-underline-user,
.nook-reader-page .nook-wave-user,
.nook-reader-page .nook-usersel,
.nook-reader-page [class*="nook-hl"],
.nook-reader-page [class*="nook-scribble"],
.nook-reader-page [class*="nook-underline"],
.nook-reader-page [class*="nook-wave"] {
    background: rgba(162, 161, 164, 0.65) !important;
    background-image: none !important;
}

/* ===== 波浪线颜色 ===== */
.nook-scribble,
.nook-wave-user {
    color: #5f5f5f !important;
    border-bottom-color: #5f5f5f !important;
    text-decoration-color: #5f5f5f !important;
}

/* ===== 直线颜色（下划线） ===== */
.nook-underline-user {
    color: #9f9f9f !important;
    border-bottom-color: #9f9f9f !important;
    text-decoration-color: #9f9f9f !important;
}

/* ===== 章节标题：不再需要额外下边距（装饰已移回上方） ===== */
.nook-ch-title {
    position: relative !important;
    overflow: visible !important;
    /* 移除 margin-bottom，让标题保持默认间距 */
}

/* ===== 章节开始的装饰：回到原始位置（标题上方） ===== */
.nook-ch-orn {
    display: block !important;          /* 或 inline-block，根据原样式决定 */
    visibility: visible !important;
    opacity: 1 !important;
    width: 40px !important;
    height: 40px !important;
    background: transparent url('https://img.baibai.cv/f/v1nkhB/1000036722.png') no-repeat center / contain !important;
    background-image: url('https://img.baibai.cv/f/v1nkhB/1000036722.png') !important;
    background-size: contain !important;
    background-repeat: no-repeat !important;
    background-position: center !important;
    border: none !important;
    padding: 0 !important;
    margin: 0 auto 10px auto !important;  /* 居中，下边距留给标题 */
    font-size: 0 !important;
    line-height: 0 !important;
    min-width: 40px !important;
    min-height: 40px !important;
    /* 取消绝对定位，回到正常文档流 */
    position: relative !important;
    top: auto !important;
    left: auto !important;
    transform: none !important;
    z-index: auto !important;
    overflow: visible !important;
}

/* 左侧小圆（5px） */
.nook-ch-orn::before {
    content: '' !important;
    position: absolute !important;
    top: 50% !important;
    left: -20px !important;
    transform: translateY(-50%) !important;
    width: 5px !important;
    height: 5px !important;
    border-radius: 50% !important;
    background: #343434 !important;
    display: block !important;
}

/* 右侧小圆（5px） */
.nook-ch-orn::after {
    content: '' !important;
    position: absolute !important;
    top: 50% !important;
    right: -20px !important;
    transform: translateY(-50%) !important;
    width: 5px !important;
    height: 5px !important;
    border-radius: 50% !important;
    background: #343434 !important;
    display: block !important;
}

/* ===== 章节末尾装饰：隐藏原有，替换为灰色颜文字 ===== */
.nook-ch-end {
    font-size: 0 !important;
    color: transparent !important;
    background: transparent !important;
    border: none !important;
    box-shadow: none !important;
    padding: 0 !important;
    margin: 0 !important;
}
.nook-ch-end::before {
    content: "‧˚₊•┈┈┈┈୨୧┈┈┈┈•‧₊˚⊹" !important;
    font-size: 14px !important;
    color: #888 !important;
    display: block !important;
    text-align: center !important;
    line-height: 1.5 !important;
    padding: 10px 0 !important;
}

/* ===== 隐藏章节标题下方的装饰线 ===== */
.nook-ch-rule {
    display: none !important;
}

/* ================================================================ */
/* ========== 便签样式（灰白黑简约韩系ins风） ====================== */
/* ================================================================ */

.nook-note {
    border: none !important;
    outline: none !important;
    box-shadow: 0 2px 8px rgba(0,0,0,0.05) !important;
    background: rgba(255, 255, 255, 0.7) !important;
    backdrop-filter: blur(16px) !important;
    -webkit-backdrop-filter: blur(16px) !important;
    border-radius: 12px !important;
    padding: 16px !important;
    overflow: hidden !important;
    color: #2c2c2c !important;
}
.nook-note::before,
.nook-note::after {
    display: none !important;
    content: none !important;
}

/* 便签头部：颜色 #9C9C9C */
.nook-note-head {
    background: #9C9C9C !important;
    padding: 10px 0 !important;
    margin: -16px -16px 0 -16px !important;
    display: flex !important;
    align-items: center !important;
    justify-content: space-between !important;
    width: auto !important;
    box-sizing: border-box !important;
    border-radius: 12px 12px 0 0 !important;
    border: none !important;
    outline: none !important;
}
.nook-note-head > * {
    background: transparent !important;
    padding: 0 12px !important;
    margin: 0 !important;
    flex: 0 1 auto !important;
    border: none !important;
    box-shadow: none !important;
    color: #ffffff !important;
}
.nook-note-ava {
    background: transparent !important;
}
.nook-note-name {
    color: #ffffff !important;
    padding-left: 4px !important;
    background: transparent !important;
    font-weight: 300 !important;
    letter-spacing: 0.5px !important;
}

/* 书写图标（头部第一个子元素） */
.nook-note-head > :first-child {
    background-image: url('https://img.baibai.cv/f/O6oBFy/1000036415.png') !important;
    background-size: contain !important;
    background-repeat: no-repeat !important;
    background-position: center !important;
    background-color: transparent !important;
    border: none !important;
    box-shadow: none !important;
    padding: 0 !important;
    margin: 6px 0 6px 12px !important;
    width: 24px !important;
    height: 24px !important;
    min-width: 24px !important;
    min-height: 24px !important;
    display: inline-block !important;
    font-size: 0 !important;
    color: transparent !important;
    border-radius: 0 !important;
    flex: 0 0 auto !important;
}

/* 取消按键 */
.nook-note-head > :last-child {
    padding: 0 !important;
    margin: 6px 12px 6px 0 !important;
    color: #ffffff !important;
    background: none !important;
    background-image: none !important;
    border: none !important;
    box-shadow: none !important;
    flex: 0 0 auto !important;
    font-size: 16px !important;
    line-height: 1 !important;
    font-weight: 300 !important;
}

/* 引用消息：背景 #ECECEC */
.nook-note .quote,
.nook-note blockquote,
.nook-note [class*="quote"],
.nook-note [class*="cite"] {
    margin-top: 16px !important;
    background-color: #ECECEC !important;
    color: #2c2c2c !important;
    border-left: 3px solid #b0b0b0 !important;
    border-radius: 4px !important;
    padding: 8px 12px !important;
    font-style: normal !important;
}

/* 便签内的按钮 */
.nook-note button,
.nook-note .nook-btn,
.nook-note [class*="btn"] {
    background-color: #3a3a3a !important;
    color: #ffffff !important;
    border: none !important;
    border-radius: 6px !important;
    padding: 4px 16px !important;
    font-size: 14px !important;
    font-weight: 300 !important;
    letter-spacing: 0.3px !important;
    transition: background 0.2s !important;
}
.nook-note button:hover,
.nook-note .nook-btn:hover {
    background-color: #555555 !important;
}

/* 便签正文 */
.nook-note-body {
    color: #2c2c2c !important;
    font-size: 15px !important;
    line-height: 1.6 !important;
}

/* 回复内容 */
.nook-note-reply {
    color: #444444 !important;
    font-size: 14px !important;
    line-height: 1.5 !important;
    border-top: 1px solid #e0e0e0 !important;
    margin-top: 12px !important;
    padding-top: 12px !important;
}

/* 移除多余的模糊效果 */
body, .nook-reader-page, .nook-reader-page * {
    backdrop-filter: none !important;
    -webkit-backdrop-filter: none !important;
}

/*⁣‌‍​⁠‍​‍​​​⁠⁠‌​‍⁠‌‍‍‌‌​​‍⁠‌⁠​​⁠⁠​‌‌‍​‍​‌‍‍‍‍‍​‍‌‌‌⁠‌‍⁠⁠​⁠⁠‍​⁠‌‍⁠‌⁣ ---------- 主容器 ---------- */
#book-nook-screen {
