  box-shadow: none !important;
}

.nook-search-box .nook-search-input:hover {
  outline: none !important;
  box-shadow: none !important;
}

/* 标签按钮 "阅读中" 和 "已完结" */
.nook-tabs .nook-tab-btn.active {
