}

/* ========== 导入弹窗 ========== */

/* 弹窗遮罩  */
.nook-modal-overlay {
  background: rgba(0, 0, 0, 0.3);
}

/* 加号弹出菜单 */
.nook-add-menu,
.nook-user-menu {
  background: #ffffff;
  border: none;
  border-radius: 12px;
  box-shadow: 0 10px 20px #505050;
}

.nook-add-menu button,
.nook-user-menu button {
  color: #505050;
  background: transparent;
  transition: background 0.2s, color 0.2s;
}

.nook-add-menu button:hover,
.nook-user-menu button:hover {
  background: #e8f0ec;
  color: #4c917c;
}

.nook-add-menu button svg,
.nook-user-menu button svg {
  color: #4c917c;
}

/* 弹窗主体 */
.nook-modal {
  background: #ffffff;
  border-radius: 20px;
  border: none;
  outline: none !important;
  box-shadow: 0 10px 20px #505050;
}

/* 弹窗头部 */
.nook-modal-head {
  border-bottom: 1px solid #4c917c;
}

.book-nook-screen .nook-modal-head svg {
  color: #4c917c;
}

.nook-modal-title {
  color: #4c917c;
}

/* 导入选项容器 */
.nook-import-choices {
  background: #ffffff;
  box-shadow: none;
}

/* 单个导入选项 */
.nook-import-choice {
  background: #f3f3f3;
  border: 1px solid #c2c2c2;
  border-radius: 14px;
  transition: background 0.2s, border-color 0.2s, box-shadow 0.2s;
  box-shadow: none;
}

.nook-import-choice:hover {
  background: #e8f0ec;
  border: none;
}

.nook-import-choice svg {
  color: #4c917c;
}

.nook-import-choice-title {
  color: #505050;
}

.nook-import-choice-sub {
  color: #c2c2c2;
}

/* 回忆录用户行 */
.nook-user-chip {
  color: #505050;
  background: #f3f3f3;
  border: 1px solid #c2c2c2;
  border-radius: 12px;
  transition: all 0.25s ease;
  outline: none;
}

/* 点击状态 */
.nook-user-chip:active {
  background: #e8f0ec;
  border-color: #57796e;
  transform: scale(0.96);
}

/* 选中/激活状态 */
.nook-user-chip.active {
  background: #e8f0ec;
  border-color: #4c917c;
  color: #505050;
}

/* 回忆录行 */
.nook-memoir-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 16px;
  background: #ffffff;
  border-radius: 12px;
  border: 1px solid #e8f0ec;
  margin-bottom: 8px;
  transition: all 0.3s ease;
}

.nook-memoir-row:hover {
  border-color: #57796e;
}

.nook-memoir-info {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.nook-memoir-title {
  font-size: 16px;
  font-weight: 600;
  color: #264a3f;
}

.nook-memoir-sub {
  font-size: 12px;
  color: #57796e;
}

.nook-memoir-acts {
  display: flex;
  gap: 10px;
}

.nook-memoir-acts button {
  padding: 6px 18px;
  border-radius: 20px;
  font-size: 13px;
  font-weight: 500;
  border: none;
  cursor: pointer;
  transition: all 0.3s ease;
}

.nook-memoir-gen {
  background: #57796e;
  color: #ffffff;
}

.nook-memoir-gen:hover {
  background: #264a3f;
  transform: translateY(-1px);
}

.nook-memoir-gen:active {
  transform: translateY(0);
}

.nook-memoir-sync {
  background: #e8f0ec;
  color: #57796e;
  font-weight: bold;
}

.nook-memoir-sync:hover:not(:disabled) {
  background: #8fb6a5;
  transform: translateY(-1px);
}

.nook-memoir-sync:disabled {
  opacity: 0.4;
  cursor: not-allowed;
  transform: none !important;
  box-shadow: none !important;
}

/* ---------- 回忆小说弹窗主体（玻璃效果） ---------- */
.hl-modal.glass.hl-novel-reader {
