  border-radius: 20px;
  display: flex;
  flex-direction: column;
  max-height: 90vh;
  overflow: hidden;
}

.hl-modal {
  border: none;
}

/* 弹窗头部 */
.hl-modal-head {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 16px 20px;
  border-bottom: 1px solid #4c917c;
  flex-shrink: 0;
}

/* 标题文字 */
.hl-modal-title {
  flex: 1;
  font-size: 18px;
  font-weight: 600;
  color: #4c917c;
