  transition: all 0.2s ease;
  flex-shrink: 0;
}

.hl-modal-back:hover,
.hl-modal-close:hover {
  background: transparent;
  color: #57796e;
}

/* 内容区（空白状态） */
.hl-novel-toc {
  flex: 1;
  overflow-y: auto;
  padding: 20px;
}

.hl-showcase-empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 10px;
  padding: 20px;
  text-align: center;
}

.hl-showcase-empty svg {
  color: #4c917c;
  opacity: 0.6;
}

.hl-showcase-empty p {
  color: #c2c2c2;
  font-size: 14px;
  line-height: 1.6;
  max-width: 280px;
  margin: 0;
}

/* 底部操作区 */
.hl-novel-foot {
  border-top: 1px solid #c2c2c2;
  border-radius: 12px 12px 0 0;
  padding: 20px;
  display: flex;
  flex-direction: column;
  gap: 16px;
  flex-shrink: 0;
  background: #ffffff;
}

/* 文风设定面板 */
.hl-novel-style {
  display: flex;
  flex-direction: column;
  gap: 10px;
  border: 1px solid #c2c2c2;
}

/* 小标题 */
.hl-novel-style-label {
  font-size: 13px;
  font-weight: 600;
  color: #4c917c;
  opacity: 1;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

/* 选项标签组 */
.hl-novel-style-chips {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

/* 单个选项标签 */
.hl-novel-chip {
  padding: 6px 14px;
  font-size: 13px;
  font-weight: 500;
  color: #505050;
  background: #ffffff;
  border: 1px solid rgba(76,145,124,0.5);
  border-radius: 20px;
  cursor: pointer;
  transition: all 0.2s ease;
  outline: none;
  white-space: nowrap;
