  max-width: 200px !important;           
  background: rgba(0,0,0,0.03) !important;
  padding: 6px 12px !important;
  border-radius: 12px !important;
}

/* 我方引用 */
.msg-reply-detached-me { align-items: flex-end !important; }
.msg-reply-detached-me .msg-reply-detached-name { 
  display: block !important; 
  font-size: 12px !important; color: #a0a0a0 !important; font-weight: 600 !important;
}
.msg-reply-detached-me .msg-reply-detached-name::before { content: "⤶ 你回复了 "; font-weight: 600; }
.msg-reply-detached-me .msg-reply-detached-text, .msg-reply-detached-me .msg-reply-detached-media {
  position: relative !important; border-radius: 12px 4px 4px 12px !important;  
}
.msg-reply-detached-me .msg-reply-detached-text::after, .msg-reply-detached-me .msg-reply-detached-media::after {
  content: ""; position: absolute; right: 0px; top: 20%; height: 60%; width: 2px !important;
  background: #000000 !important; border-radius: 2px !important;
}

/* 对方引用 */
.msg-reply-detached-them { align-items: flex-start !important; }
.msg-reply-detached-them .msg-reply-detached-name { display: none !important; }
.msg-reply-detached-them::before {
