.msg-reply-detached-them .msg-reply-detached-text::before, .msg-reply-detached-them .msg-reply-detached-media::before {
  content: ""; position: absolute; left: 0px; top: 20%; height: 60%; width: 2px !important;
  background: #000000 !important; border-radius: 2px !important;
}

/* 引用图压扁为缩略图 & 大图限制 */
.msg-reply-block-detached img, .msg-reply-block-detached video {
