}
:root { --image-msg-max-width: 200px; }
.msg-image-wrapper, .msg-sim-card { max-width: 200px !important; max-height: 280px !important; }
.msg-image-wrapper img, .msg-sim-card img { max-width: 100% !important; max-height: 280px !important; object-fit: cover !important; }
.msg-me .msg-image-wrapper, .msg-me .msg-sim-card { min-width: 140px !important; min-height: 140px !important; }

/* 纯贴图转账卡 */
:root {
