  background-repeat: no-repeat !important;
  background-size: 23px 23px, 23px 23px, 24px 24px !important;
  background-position:
    16.6667% center,
    50% center,
    83.3333% center !important;
}

/* 第 4 项：铃铛 = 贴纸按钮；中心固定在 70% */
.input-btn-sticker {
