/* 最终修复：新版语音条由 controls-row 承担圆形背景 */
.chat-messages-area[data-theme-style="plain"] .voice-msg,
.chat-messages-area[data-theme-style="plain"] .voice-msg-me,
.chat-messages-area[data-theme-style="plain"] .voice-msg-them {
