  font-family: -apple-system, BlinkMacSystemFont, "SF Pro Rounded", "Arial Rounded MT Bold", sans-serif !important;

  /* 👇 【核心根治】用原生矢量描边取代容易产生噪点的 text-shadow，彻底消除蚂蚁线！ */
  -webkit-text-stroke: 2px #000000 !important;  /* 👈 丝滑平滑的纯黑外描边 */
