  height: 42px !important; 
  min-width: 42px !important; 
  max-width: 42px !important;
  border-radius: 50% !important; 
  background: var(--bubble-me-bg, #007aff) !important; 
  box-shadow: 0 4px 14px rgba(0, 122, 255, 0.38) !important;
