  margin-left: 2px !important; margin-right: 0 !important; white-space: nowrap !important;
}

.voice-download-btn {
  display: inline-flex !important; width: 18px !important; height: 18px !important; min-width: 18px !important;
  opacity: 0.55 !important; cursor: pointer !important; margin-left: 2px !important;
  align-items: center !important; justify-content: center !important; transition: opacity 0.15s ease !important; z-index: 2 !important;
}
.voice-download-btn:active { opacity: 1 !important; }
.voice-download-btn svg { width: 13px !important; height: 13px !important; }

/* 5. 波形触控展开转文字 */
body, :root { --voice-toggle-opacity: 0 !important; --voice-toggle-size: 1px !important; }
[class*="voice-transcription-toggle"],
[class*="voice-toggle"] {
  position: absolute !important; inset: 0 0 0 40px !important;
  width: auto !important; height: 100% !important; opacity: 0 !important;
  z-index: 10 !important; margin: 0 !important; padding: 0 !important;
  cursor: pointer !important; display: block !important;
}

.voice-transcription {
  display: block !important; font-size: 13px !important; line-height: 1.4 !important;
  margin-top: 4px !important; padding: 6px 8px !important; border-radius: 8px !important;
  background: rgba(120, 120, 128, 0.12) !important;
}
.bubble-me-custom .voice-transcription {
  background: rgba(255, 255, 255, 0.18) !important; color: #ffffff !important;
}

/* =========================================================
   9.1. 👇【语音小尾巴：严格锁定只在连发最后一条/单条才出现】
   ========================================================= */

/* 连发的前面条目 (.is-first / .is-mid) 绝对禁止长尾巴 */
.msg-bubble-wrapper.is-first:has(.voice-msg) .bubble-me-custom::before,
.msg-bubble-wrapper.is-mid:has(.voice-msg) .bubble-me-custom::before,
.msg-bubble-wrapper.is-first:has(.voice-msg) .bubble-them-custom::before,
.msg-bubble-wrapper.is-mid:has(.voice-msg) .bubble-them-custom::before {
  display: none !important;
  content: none !important;
}

/* 只有属于最后一条 (.is-last) 或 单发一条 (.is-single) 时长出尾巴 */
.msg-bubble-wrapper.is-last.msg-me:has(.voice-msg) .bubble-me-custom::before,
.msg-bubble-wrapper.is-single.msg-me:has(.voice-msg) .bubble-me-custom::before {
  display: block !important;
}
.msg-bubble-wrapper.is-last.msg-them:has(.voice-msg) .bubble-them-custom::before,
.msg-bubble-wrapper.is-single.msg-them:has(.voice-msg) .bubble-them-custom::before {
  display: block !important;
}

/* =========================================================
   9.2. 👇【Raise to listen / talk：严格锁定只在收尾时出现 + 0重叠】
   ========================================================= */

/* 清除其他容易穿模的伪元素残余 */
.msg-bubble-container:has(.voice-msg)::after,
.bubble-me-custom:has(.voice-msg)::after,
.bubble-them-custom:has(.voice-msg)::after {
  display: none !important;
  content: none !important;
}

/* --- 对方语音提示：仅在 .is-last 或 .is-single 时挂载 Raise to listen --- */

.msg-bubble-wrapper.is-last.msg-them:has(.voice-msg) .msg-content-stack::after,
.msg-bubble-wrapper.is-single.msg-them:has(.voice-msg) .msg-content-stack::after {
  content: "Raise to listen" !important;
  display: block !important;
  margin-top: 5px !important;
  margin-left: 4px !important;
  font-family: -apple-system, BlinkMacSystemFont, "SF Pro Text", sans-serif !important;
  font-size: 11.5px !important;
  font-weight: 600 !important;
  color: var(--text-sub) !important;
  letter-spacing: -0.1px !important;
  white-space: nowrap !important;
  line-height: 1.2 !important;
  text-align: left !important;
}

/* --- 我方语音提示：仅在 .is-last 或 .is-single 时挂载 Raise to talk --- */
.msg-bubble-wrapper.is-last.msg-me:has(.voice-msg) .msg-status-custom::before,
.msg-bubble-wrapper.is-single.msg-me:has(.voice-msg) .msg-status-custom::before {
  content: "Raise to talk" !important;
  display: block !important;
  text-align: right !important;
  font-family: -apple-system, BlinkMacSystemFont, "SF Pro Text", sans-serif !important;
  font-size: 11.5px !important;
  font-weight: 600 !important;
  color: var(--text-sub) !important;
  letter-spacing: -0.1px !important;
  margin-bottom: 2px !important; /* 👈 与下面的已读时间完全错开，上下排布绝对不重叠 */
  line-height: 1.2 !important;
}

/* 连发前面的语音，清除可能出现的前缀 */
.msg-bubble-wrapper.is-first:has(.voice-msg) .msg-status-custom::before,
.msg-bubble-wrapper.is-mid:has(.voice-msg) .msg-status-custom::before {
  display: none !important;
  content: none !important;
}

/* 仅在最后一条/单条语音下方留出避让间距 */
.msg-bubble-wrapper.is-last:has(.voice-msg),
.msg-bubble-wrapper.is-single:has(.voice-msg) {
  margin-bottom: 14px !important;
}

/* =========================================================
   10. 🎚️ 【思维链微型开关 (永居引用条最上方 -2)】
   ========================================================= */
:root {
  --neu-w: 32px;
  --neu-h: 16px;
  --neu-knob: 10.5px;
  --neu-pad: 2.75px;
}

.nuo-thinking-wrap {
  align-items: flex-start !important;
  width: fit-content !important;  
  margin-bottom: 4px !important;
  order: -2 !important;
}

.nuo-thinking-btn {
  position: relative !important;
  display: inline-flex !important; 
  align-items: center !important;
  justify-content: flex-start !important;
  width: var(--neu-w) !important;
  height: var(--neu-h) !important;
  min-height: var(--neu-h) !important;
  border-radius: calc(var(--neu-h) / 2) !important;
  background: var(--knob-holder-bg) !important;
  border: none !important;
  padding: 0 !important;
  box-shadow:
    -1.5px -1.5px 4px var(--knob-light),
     1.5px  1.5px 4px var(--knob-dark) !important;
  transform: none !important;
  overflow: visible !important;
  flex-shrink: 0 !important; 
}

.nuo-thinking-btn .nuo-thinking-arrow,
.nuo-thinking-btn .nuo-thinking-icon,
.nuo-thinking-btn .nuo-thinking-label,
.nuo-thinking-btn::after {
  display: none !important;
}

.nuo-thinking-btn::before {
  content: "" !important;
  position: absolute !important;
  top: var(--neu-pad) !important;
  left: var(--neu-pad) !important;
  width: var(--neu-knob) !important;
  height: var(--neu-knob) !important;
  border-radius: 50% !important;
  background: #ffffff !important;
  box-shadow: 
    0 0 4px rgba(0, 0, 0, 0.15),
    0 0 1px rgba(0, 0, 0, 0.2) !important;
  transition: left .25s cubic-bezier(0.4, 0, 0.2, 1), box-shadow .25s !important;
  z-index: 2 !important;
  pointer-events: none !important;
}

.nuo-thinking-wrap:has(.nuo-thinking-panel:not([style*="display: none"]):not([hidden])) .nuo-thinking-btn::before,
.nuo-thinking-btn.active::before,
.nuo-thinking-btn[aria-expanded="true"]::before {
  left: calc(var(--neu-w) - var(--neu-knob) - var(--neu-pad)) !important;
}

/* 夜间思维链圆钮改灰色 */
@media (prefers-color-scheme: dark) {
  .nuo-thinking-btn::before {
    background: #636366 !important;
    box-shadow:
      0 0 4px rgba(0, 0, 0, 0.4),
      0 0 1px rgba(0, 0, 0, 0.5) !important;
  }
}

/* =========================================================
   11. 【返回键黑点直接状态变色 -> 尺寸绝对100%一致】
   ========================================================= */
.chat-header-custom .nuo-chat-header-unread-num,
.chat-header-custom .header-btn-back .nuo-chat-header-unread-dot {
  display: none !important;
  visibility: hidden !important;
  opacity: 0 !important;
  width: 0 !important;
  height: 0 !important;
}

.chat-header-custom .header-btn-back:has(.nuo-chat-header-unread-dot)::before {
  background-color: #ff3b30 !important;
  box-shadow: 0 1px 4px rgba(255, 59, 48, 0.4) !important;
}

/* =========================================================
   【补丁：纯净表情包/图片 (精准隔离版·绝不误杀正常文本尾巴)】感谢池渝的源代码，基于原来的基础上加上去掉小尾巴伪元素
   ========================================================= */

/* 1. 仅当“气泡本体内部”直接装了图片时，才精准掐灭这个气泡自己的尾巴 (绝不污染其他消息) */
.bubble-me-custom:has(.msg-image-wrapper)::before,
.bubble-me-custom:has(.msg-image-wrapper)::after,
.bubble-them-custom:has(.msg-image-wrapper)::before,
.bubble-them-custom:has(.msg-image-wrapper)::after,
.bubble-me-custom:has(img:not([class*="reply"] img))::before,
.bubble-me-custom:has(img:not([class*="reply"] img))::after,
.bubble-them-custom:has(img:not([class*="reply"] img))::before,
.bubble-them-custom:has(img:not([class*="reply"] img))::after {
  display: none !important;
  content: none !important;
  opacity: 0 !important;
  visibility: hidden !important;
}

/* 2. 仅当气泡内部装了图片时，该气泡外壳全透明、去内边距 */
.bubble-me-custom:has(.msg-image-wrapper),
.bubble-them-custom:has(.msg-image-wrapper),
.bubble-me-custom:has(img:not([class*="reply"] img)),
.bubble-them-custom:has(img:not([class*="reply"] img)) {
  background: transparent !important;
  background-color: transparent !important;
  border: none !important;
  box-shadow: none !important;
  padding: 0 !important;
}

/* 3. 控制聊天区图片/表情包尺寸与圆角 */
.msg-bubble-container img:not([class*="reply"] img) {
  max-width: 110px !important; 
  max-height: 170px !important;
  width: auto !important;
  height: auto !important;
  object-fit: contain !important;
  border-radius: 8px !important;
}

/* 发出的图片靠右对齐 */
.msg-me .msg-bubble-container img:not([class*="reply"] img) {
  display: block !important;
  margin-left: auto !important;
  margin-right: 0 !important;
}

/* 收到的图片靠左对齐 */
.msg-them .msg-bubble-container img:not([class*="reply"] img) {
  display: block !important;
  margin-right: auto !important;
  margin-left: 0 !important;
}

.msg-image-wrapper, 
.msg-bubble-container:has(img:not([class*="reply"] img)) {
  height: auto !important;
  min-height: 0 !important;
}

/* 4. 引用框内部的微缩正方形小图保持 28px */
div[class*="reply"] img,
.msg-reply-block-detached img,
.msg-reply-detached-text img {
  width: 28px !important;
  height: 28px !important;
  min-width: 28px !important;
  max-width: 28px !important; 
  max-height: 28px !important;
  object-fit: cover !important; 
  aspect-ratio: 1 / 1 !important; 
  border-radius: 4px !important;
  vertical-align: middle !important;
  display: inline-block !important;
  margin: 0 4px !important;
}

/* =========================================================
   【补丁：终极锁定夜间白心黑圈 (10px标准原版尺寸·绝不缩水)】
   ========================================================= */
@media (prefers-color-scheme: dark) {
  .chat-header-custom .header-btn-back::before {
    width: 10px !important;                      /* 👈 锁死 10px 绝对尺寸 */
    height: 10px !important;                     /* 👈 锁死 10px 绝对尺寸 */
    right: -2px !important;                      /* 👈 锁死标准坐标 */
    bottom: 0px !important;                      /* 👈 锁死标准坐标 */
    box-sizing: content-box !important;          /* 确保 2px 边框向外撑开，不吃掉 10px 白心 */
    background: #ffffff !important;              /* 👈 纯白心 */
    border: 2px solid #000000 !important;        /* 👈 纯黑圈 */

    border-radius: 50% !important;
    z-index: 2 !important;
  }
}

/* =========================================================
   【补丁：夜间顶栏头像框 -> 深灰边框】
   ========================================================= */
@media (prefers-color-scheme: dark) {
  .chat-header-custom .header-avatar-container {
    /* 👈 彻底锁死实体深空灰 (去除任何白色 rgb 泛光) */
    border: 2px solid #3a3a3c !important; 
    box-shadow: 0 1px 4px rgba(0, 0, 0, 0.5) !important;
  }
}

/* =========================================================
   【补丁：夜间模式对方语音条 -> 浅白高光波形与文字】
   ========================================================= */
@media (prefers-color-scheme: dark) {
  /* 1. 变量层夜间反白 */
  :root, body, .chat-detail-screen {
    --voice-them-bar-active: rgba(255, 255, 255, 0.88) !important;
    --voice-them-bar-inactive: rgba(255, 255, 255, 0.28) !important;
  }

  /* 2. 节点层强制浅白上色 (绝不发灰) */
  .bubble-them-custom .voice-waveform-bar,
  .msg-them .voice-waveform-bar {
    background-color: rgba(255, 255, 255, 0.88) !important;
  }

  /* 对方时长数字同步为清亮浅白 */
  .bubble-them-custom .voice-duration,
  .msg-them .voice-duration {
    color: #f5f5f7 !important;
  }

  /* 下载小图标同步提亮 */
  .bubble-them-custom .voice-download-btn,
  .msg-them .voice-download-btn {
    opacity: 0.75 !important;
    filter: invert(1) !important;
  }
}

/* =========================================================
   【补丁：底栏提示条多层阶梯累加引擎 (出几个就精确抬高几层)】
   ========================================================= */

/* 1. 定义单个提示条的标准高度单位 (含 margin 间距正好为 38px) */
:root {
  --bar-step-height: 38px;
}

/* 2. 底栏外壳保持绝对定位穿透 */
.input-area-custom {
  position: absolute !important;
  bottom: 0 !important;
  left: 0 !important;
  right: 0 !important;
  background: transparent !important;
  border: none !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
  padding: 10px 12px calc(env(safe-area-inset-bottom, 12px) + 12px) 12px !important;
  margin-top: 0 !important;
  z-index: 100 !important;
  pointer-events: none !important;
}

/* ---------------------------------------------------------
   3. 阶梯累加器：根据实际出现的条目数量逐级向上托起消息
   --------------------------------------------------------- */

/* 【第一阶台阶】：只要出现任意 1 条提示条 (旁白 / 身份 / 回复预览) -> 精准抬高 1 个单位 */
.chat-detail-screen:has(.input-sendas-bar) .chat-messages-area,
.chat-detail-screen:has(.input-sendas-bar) .chat-message-list-custom,
.chat-detail-screen:has(.input-reply-preview-bar) .chat-messages-area,
.chat-detail-screen:has(.input-reply-preview-bar) .chat-message-list-custom,
.chat-detail-screen:has([class*="sendas-bar"]) .chat-messages-area,
.chat-detail-screen:has([class*="sendas-bar"]) .chat-message-list-custom {
  padding-bottom: calc(var(--list-bottom-clearance) + var(--bar-step-height)) !important;
}

/* 【第二阶台阶】：同时出现任意 2 条提示条 -> 精准累加抬高 2 个单位 (38px × 2) */
.chat-detail-screen:has(.input-sendas-bar ~ .input-sendas-bar) .chat-messages-area,
.chat-detail-screen:has(.input-sendas-bar ~ .input-sendas-bar) .chat-message-list-custom,
.chat-detail-screen:has(.input-reply-preview-bar ~ .input-sendas-bar) .chat-messages-area,
.chat-detail-screen:has(.input-reply-preview-bar ~ .input-sendas-bar) .chat-message-list-custom,
.chat-detail-screen:has([class*="sendas-bar"] ~ [class*="sendas-bar"]) .chat-messages-area,
.chat-detail-screen:has([class*="sendas-bar"] ~ [class*="sendas-bar"]) .chat-message-list-custom {
  padding-bottom: calc(var(--list-bottom-clearance) + (var(--bar-step-height) * 2)) !important;
}

/* 【第三阶台阶】：极限状态同时出现 3 条提示条 -> 精准累加抬高 3 个单位 (38px × 3) */
.chat-detail-screen:has(.input-reply-preview-bar ~ .input-sendas-bar ~ .input-sendas-bar) .chat-messages-area,
.chat-detail-screen:has(.input-reply-preview-bar ~ .input-sendas-bar ~ .input-sendas-bar) .chat-message-list-custom,
.chat-detail-screen:has([class*="sendas-bar"] ~ [class*="sendas-bar"] ~ [class*="sendas-bar"]) .chat-messages-area,
.chat-detail-screen:has([class*="sendas-bar"] ~ [class*="sendas-bar"] ~ [class*="sendas-bar"]) .chat-message-list-custom {
  padding-bottom: calc(var(--list-bottom-clearance) + (var(--bar-step-height) * 3)) !important;
}

/* 

4.=========================================================
   【补丁：正在回复预览条高度自适应 (Auto Height 彻底防溢出)】
   ========================================================= */

/* 1. 单行模式条 (旁白/身份)：保持 32px 紧凑高度 */
.input-sendas-bar,
[class*="sendas-bar"] {
  height: 32px !important;
  min-height: 32px !important;
  box-sizing: border-box !important;
  background: var(--ios-glass-bg) !important;
  backdrop-filter: var(--ios-glass-blur) !important;
  -webkit-backdrop-filter: var(--ios-glass-blur) !important;
  border-radius: 12px !important;
  border: var(--ios-glass-border) !important;
  box-shadow: 0 3px 12px rgba(0, 0, 0, 0.05) !important;
  padding: 0 12px !important;
  margin: 0 4px 6px 4px !important;
  pointer-events: auto !important;
  display: flex !important;
  align-items: center !important;
  justify-content: space-between !important;
}

/* 2. 👇【核心修复】双行回复预览条：解除高度锁死，彻底自适应任何个性字体 */
.input-reply-preview-bar,
[class*="reply-preview-bar"] {
  height: auto !important;          /* 👈 解除高度锁死，允许随字体自由撑开 */
  min-height: 44px !important;      /* 保底高度 */
  box-sizing: border-box !important;
  background: var(--ios-glass-bg) !important;
  backdrop-filter: var(--ios-glass-blur) !important;
  -webkit-backdrop-filter: var(--ios-glass-blur) !important;
  border-radius: 14px !important;
  border: var(--ios-glass-border) !important;
  box-shadow: 0 4px 14px rgba(0, 0, 0, 0.06) !important;
  padding: 6px 12px 6px 8px !important;
  margin: 0 4px 6px 4px !important;
  pointer-events: auto !important;
  display: flex !important;
  align-items: center !important;
  justify-content: space-between !important;
  position: relative !important;
}

/* 回复条左侧蓝色竖线：自适应整张卡片的高度 */
.input-reply-preview-bar::before,
[class*="reply-preview-bar"]::before {
  content: "" !important;
  width: 3px !important;
  height: calc(100% - 12px) !important; /* 上下各留 6px 边距，随卡片高度自适应 */
  background-color: var(--bubble-me-bg, #007aff) !important;
  border-radius: 2px !important;
  margin-right: 8px !important;
  flex-shrink: 0 !important;
}

/* 中间两行文字排版区域 */
.input-reply-preview-content,
[class*="reply-preview-content"] {
  flex: 1 !important;
  min-width: 0 !important;
  display: flex !important;
  flex-direction: column !important;
  justify-content: center !important;
  gap: 2px !important;
}

/* 第一行：「正在回复 某某」 */
.input-reply-preview-name,
[class*="reply-preview-name"] {
  font-family: -apple-system, BlinkMacSystemFont, "SF Pro Text", sans-serif !important;
  font-size: 11.5px !important;
  font-weight: 600 !important;
  color: var(--bubble-me-bg, #007aff) !important;
  line-height: 1.2 !important;
}

/* 第二行：被引用的正文内容 */
.input-reply-preview-text,
[class*="reply-preview-text"] {
  font-family: -apple-system, BlinkMacSystemFont, "SF Pro Text", sans-serif !important;
  font-size: 12.5px !important;
  font-weight: 400 !important;
  color: var(--text-sub, #8e8e93) !important;
  line-height: 1.25 !important;
  white-space: nowrap !important;
  overflow: hidden !important;
  text-overflow: ellipsis !important;
  max-width: 220px !important;
}

/* 提示条内部文字 */
.input-sendas-label,
[class*="sendas-label"] {
  font-family: -apple-system, BlinkMacSystemFont, "SF Pro Text", sans-serif !important;
  font-size: 12px !important;
  font-weight: 500 !important;
  color: var(--text-main) !important;
  letter-spacing: -0.2px !important;
  line-height: 1 !important;
}

.input-sendas-char-bar .input-sendas-label,
[class*="sendas-char"] [class*="sendas-label"] {
  color: var(--bubble-me-bg) !important;
  font-weight: 600 !important;
}

.input-sendas-narration-bar .input-sendas-label,
[class*="sendas-narration"] [class*="sendas-label"] {
  color: var(--text-sub) !important;
  font-style: italic !important;
}

/* 右侧关闭「×」按键 (强制在自适应卡片中绝对垂直居中) */
.input-sendas-close,
.input-reply-preview-close,
[class*="sendas-close"],
[class*="reply-preview-close"] {
  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;
  width: 20px !important;
  height: 20px !important;
  min-width: 20px !important;
  min-height: 20px !important;
  padding: 0 !important;
  margin: 0 !important;
  line-height: 1 !important;
  font-size: 15px !important;
  color: var(--text-sub) !important;
  opacity: 0.65 !important;
  cursor: pointer !important;
  align-self: center !important; /* 👈 随卡片自动居中 */
  flex-shrink: 0 !important;
}
.input-sendas-close:active,
.input-reply-preview-close:active {
  opacity: 1 !important;
  transform: scale(0.9) !important;
}

/* ===== 锁死发送键大小，强制关闭软件自带的动画by烧酒酒 ===== */
.send-btn-custom,
.send-btn-custom:active,
.send-btn-custom:focus {
