    background-image: none !important;
}

/* ===== 波浪线颜色 ===== */
.nook-scribble,
.nook-wave-user {
    color: #5f5f5f !important;
    border-bottom-color: #5f5f5f !important;
    text-decoration-color: #5f5f5f !important;
}

/* ===== 直线颜色（下划线） ===== */
.nook-underline-user {
    color: #9f9f9f !important;
    border-bottom-color: #9f9f9f !important;
    text-decoration-color: #9f9f9f !important;
}

/* ===== 章节标题：不再需要额外下边距（装饰已移回上方） ===== */
.nook-ch-title {
    position: relative !important;
    overflow: visible !important;
    /* 移除 margin-bottom，让标题保持默认间距 */
}

/* ===== 章节开始的装饰：回到原始位置（标题上方） ===== */
.nook-ch-orn {
    display: block !important;          /* 或 inline-block，根据原样式决定 */
    visibility: visible !important;
    opacity: 1 !important;
    width: 40px !important;
    height: 40px !important;
    background: transparent url('https://img.baibai.cv/f/v1nkhB/1000036722.png') no-repeat center / contain !important;
    background-image: url('https://img.baibai.cv/f/v1nkhB/1000036722.png') !important;
    background-size: contain !important;
    background-repeat: no-repeat !important;
    background-position: center !important;
    border: none !important;
    padding: 0 !important;
    margin: 0 auto 10px auto !important;  /* 居中，下边距留给标题 */
    font-size: 0 !important;
    line-height: 0 !important;
    min-width: 40px !important;
    min-height: 40px !important;
    /* 取消绝对定位，回到正常文档流 */
    position: relative !important;
    top: auto !important;
    left: auto !important;
    transform: none !important;
    z-index: auto !important;
    overflow: visible !important;
}

/* 左侧小圆（5px） */
.nook-ch-orn::before {
    content: '' !important;
    position: absolute !important;
    top: 50% !important;
    left: -20px !important;
    transform: translateY(-50%) !important;
    width: 5px !important;
    height: 5px !important;
    border-radius: 50% !important;
    background: #343434 !important;
    display: block !important;
}

/* 右侧小圆（5px） */
.nook-ch-orn::after {
    content: '' !important;
    position: absolute !important;
    top: 50% !important;
    right: -20px !important;
    transform: translateY(-50%) !important;
    width: 5px !important;
    height: 5px !important;
    border-radius: 50% !important;
    background: #343434 !important;
    display: block !important;
}

/* ===== 章节末尾装饰：隐藏原有，替换为灰色颜文字 ===== */
.nook-ch-end {
    font-size: 0 !important;
    color: transparent !important;
    background: transparent !important;
    border: none !important;
    box-shadow: none !important;
    padding: 0 !important;
    margin: 0 !important;
}
.nook-ch-end::before {
    content: "‧˚₊•┈┈┈┈୨୧┈┈┈┈•‧₊˚⊹" !important;
    font-size: 14px !important;
