:root {
    --roster-layout: grid;
    --roster-detail: tarot;
    --roster-grid-min: 100%;
    --roster-card-ratio: auto;
    --roster-act-tint: #576b95;

    --roster-bg: #ededed;
    --roster-panel: #ffffff;
    --roster-header: #f7f7f7;
    --roster-line: #e8e8e8;
    --roster-text: #1a1a1a;
    --roster-muted: #888888;
    --roster-accent: #576b95;
    --roster-accent-soft: #eef1f7;
    --roster-pop: #4c4c4c;


    --rg-gold: #576b95;
    --rg-gold-hi: #8fa0c4;
    --rg-cream: #e5e5e5;
    --rg-muted: #888888;
    --rg-wine: #576b95;
    --rg-gold-grad: linear-gradient(135deg, #576b95, #6f82aa);
    --rs-gold: #576b95;
    --rjs-gold: #576b95;
}

.roster-app-container {
    background: var(--roster-bg) !important;
    color: var(--roster-text) !important;
}
.roster-stardust {
    display: none !important;
}
.roster-app-container,
.premium-card,
.premium-card .card-avatar-container,
.premium-card .roster-nameplate {
    box-sizing: border-box;
}
.roster-app-container button,
.roster-app-container [role="button"],
.roster-app-container .tarot-act {
    -webkit-tap-highlight-color: transparent;
    touch-action: manipulation;
}

.roster-content {
    overscroll-behavior-y: contain;
    -webkit-overflow-scrolling: touch;
}

.roster-header {
    background: var(--roster-header) !important;
    color: var(--roster-text) !important;
    border: 0 !important;
    border-bottom: 1px solid var(--m-line,#dedede) !important;
    border-radius: 0 !important;
    box-shadow: none !important;
    backdrop-filter: none !important;
    -webkit-backdrop-filter: none !important;
}
.roster-title {
    color: var(--roster-text) !important;
    text-shadow: none !important;
    letter-spacing: 0 !important;
}
.roster-title::before,
.roster-title::after {
    display: none !important;
}
.icon-btn {
    color: var(--roster-accent) !important;
    text-shadow: none !important;
}

.roster-search-bar,
.roster-sub-header {
    background: var(--roster-header) !important;
    border-color: var(--roster-line) !important;
    box-shadow: none !important;
}
.roster-search-bar input,
.roster-search-bar input:focus {
    background: var(--m-field,#e9e9e9) !important;
    color: var(--roster-text) !important;
    border: 0 !important;
    outline: none !important;
    box-shadow: none !important;
}
