    background-repeat: no-repeat !important;
}
.roster-fab-item:first-child {
    background-image: none !important;
}
.roster-fab-item:active {
    background-color: var(--m-chip,#f2f2f2) !important;
}
.roster-fab-item .fab-popup-icon {
