.roster-tarot-detail.roster-tarot-detail.roster-tarot-detail [class*="detail-style"] > *,
.roster-tarot-detail.roster-tarot-detail.roster-tarot-detail .tarot-actions > :not(.tarot-act)::before,
.roster-tarot-detail.roster-tarot-detail.roster-tarot-detail [class*="style-btn"]::before,
.roster-tarot-detail.roster-tarot-detail.roster-tarot-detail [class*="detail-style"]::before {
