}
.xt-text-xh_rest {
  padding: 12px 16px 12px;
  background: #f9fafc;
  border: 1px solid #ff3055;
  border-top: none;
  border-bottom: none;
  border-radius: 0;
  font-size: 13px; line-height: 2;
  color: #18191a;
  margin: 0 !important;
}
.xt-text-xh_mycmt {
  padding: 8px 12px 10px;
  background: #fdf0f3;
  border: 1px solid #ff3055;
  border-top: none;
  border-radius: 0 0 14px 14px;
  font-size: 12.5px; line-height: 1.75;
  color: #18191a;
  margin: 0 !important;
}
.xt-text-xh_mycmt::before {
  content: "我的评论";
  display: block;
  font-size: 10px; font-weight: 700;
