  color: #ff3055;
  margin-bottom: 4px;
}
/* ===== 第8段 · 游戏+相册 ===== */
.xt-text-game {
  position: relative;
  padding: 14px 16px 30px;
  background: linear-gradient(135deg, #241f3d, #151226);
  border: 1px solid rgba(139,124,240,0.4);
  border-left: 3px solid #8b7cf0;
  border-radius: 14px;
  font-size: 13.5px; line-height: 2;
  color: #f5f5f3;
}
.xt-text-game::first-line {
  color: #b8a8ff;
  font-weight: 700;
}
.xt-text-game::before {
  content: "";
  position: absolute;
  top: 0; left: 0; right: 0;
  height: 4px;
  background: linear-gradient(90deg, #8b7cf0, rgba(139,124,240,0.2));
  border-radius: 12px 12px 0 0;
}
.xt-text-game::after {
  content: "";
  position: absolute;
  left: 16px; right: 16px; bottom: 10px;
  height: 5px;
  border-radius: 3px;
  background: linear-gradient(90deg, #8b7cf0 0 70%, rgba(255,255,255,0.08) 70% 100%);
}
.xt-text-album_1,
.xt-text-album_2,
.xt-text-album_3 {
  position: relative;
  padding: 14px 16px;
  background: linear-gradient(160deg, #1c1c20, #131316);
  border: 1px solid rgba(255,255,255,0.07);
  border-radius: 16px;
  font-size: 13.5px; line-height: 2;
  color: rgba(245,245,243,0.85);
