  border-radius: 12px 12px 4px 12px !important;
  padding: 7px 11px;
  font-size: 12.5px; line-height: 1.65;
  color: #ffffff !important;
}
/* ===== 第12段 · 通话/收藏/好友 ===== */
.xt-text-call {
  position: relative;
  padding: 10px 12px 10px 14px;
  background: #1e1e22;
  border: 1px solid rgba(255,255,255,0.07);
  border-left: 3px solid #c9a86a;
  border-radius: 12px;
  font-size: 12px; line-height: 1.9;
  color: rgba(245,245,243,0.8);
}
.xt-text-call::first-line {
  color: #c9a86a;
  font-weight: 700;
}
.xt-text-call::after {
  content: "";
  position: absolute;
  right: 12px; top: 14px;
  width: 7px; height: 7px;
  border-radius: 50%;
  background: #e74c3c;
  box-shadow: 0 0 4px rgba(231,76,60,0.5);
}
.xt-text-fav {
  position: relative;
  padding: 10px 14px 10px 34px;
  background: #211f1b;
  border: 1px solid rgba(201,168,106,0.15);
  border-left: 3px solid #c9a86a;
  border-radius: 12px;
  font-size: 13.5px; line-height: 2;
  color: rgba(245,245,243,0.8);
}
