value.customCss:
/*⁣‌‍​⁠‍​‍​​​⁠⁠‌​‍⁠‌‍‍‌‌​​‍⁠‌⁠​​⁠⁠​‌‌‍​‍​‌‍‍‍‍‍​‍‌‌‌⁠‌‍⁠⁠​⁠⁠‍​⁠‌‍⁠‌⁣ ==========================================================
   地球Online梦向论坛
   动态主帖 + 七条网友回复
   ========================================================== */


/* ==========================================================
   1. 整体容器
   ========================================================== */

.xt-root {
  --xt-bg: #ffffff;
  --xt-text: #151515;
  --xt-text-sub: #687782;
  --xt-text-muted: #97a2aa;
  --xt-accent: #159bd3;
  --xt-accent-bg: rgba(21, 155, 211, 0.09);
  --xt-border: #e5e9ec;
  --xt-radius: 18px;
  --xt-radius-sm: 8px;

  --xt-font:
    -apple-system,
    BlinkMacSystemFont,
    "PingFang SC",
    "Microsoft YaHei",
    sans-serif;

  --xt-anim-duration: 0.45s;
  --xt-anim-easing:
    cubic-bezier(0.22, 1, 0.36, 1);

  position: relative;

  width: 100%;
  max-width: 460px;
  height: 76vh !important;
  min-height: 520px;
  max-height: 760px !important;

  margin: 0 auto;
  padding: 58px 0 0 !important;

  box-sizing: border-box;

  overflow-y: auto !important;
  overflow-x: hidden !important;

  -webkit-overflow-scrolling: touch !important;
  overscroll-behavior-y: contain;
  touch-action: pan-y !important;

  color: #151515 !important;
  background: #ffffff !important;

  border: 1px solid #e8eaed !important;
  border-radius: 18px !important;

  box-shadow:
    0 10px 35px rgba(0, 0, 0, 0.07) !important;

  font-family: var(--xt-font) !important;

  scrollbar-width: thin;
  scrollbar-color: #d7dce0 transparent;
}


/* ==========================================================
   2. 内容区域
   ========================================================== */

.xt-content {
  position: relative;

  width: 100%;
  height: auto !important;
  min-height: max-content !important;

  margin: 0 !important;
  padding: 0 !important;

  box-sizing: border-box;

  overflow: visible !important;
  background: #ffffff !important;

  touch-action: pan-y !important;
}


/* ==========================================================
   3. 顶部返回和菜单
   ========================================================== */

.xt-root::before {
  content: "‹";

  position: absolute;
  top: 4px;
  left: 18px;
  z-index: 20;

  width: 34px;
  height: 46px;

  color: #111111;

  font-family: Arial, sans-serif;
  font-size: 48px;
  font-weight: 300;
  line-height: 44px;

  pointer-events: none;
}

.xt-root::after {
  content: "•••";

  position: absolute;
  top: 13px;
  right: 19px;
  z-index: 20;

  color: #657681;

  font-family: Arial, sans-serif;
  font-size: 16px;
  font-weight: 700;
  line-height: 24px;
  letter-spacing: 3px;

  pointer-events: none;
}


/* ==========================================================
   4. 发帖人资料
   ========================================================== */

.xt-header {
  display: flex !important;
  align-items: center !important;
  justify-content: flex-start !important;
  gap: 13px !important;

  width: 100%;

  margin: 0 !important;
  padding: 17px 20px 10px !important;

  box-sizing: border-box;

  background: #ffffff !important;

  border: 0 !important;
  border-radius: 0 !important;

  box-shadow: none !important;
}

.xt-avatar {
  width: 56px !important;
  height: 56px !important;
  min-width: 56px !important;
  flex: 0 0 56px !important;

  object-fit: cover;

  background: #eeeeee !important;

  border: 0 !important;
  border-radius: 50% !important;

  box-shadow: none !important;
}

.xt-name {
  display: flex !important;
  flex-direction: column;
  align-items: flex-start !important;
  gap: 2px;

  margin: 0 !important;
  padding: 0 !important;

  color: #151515 !important;
  background: transparent !important;

  font-size: 18px !important;
  font-weight: 750 !important;
  line-height: 1.35 !important;
  letter-spacing: 0 !important;
}

.xt-name::after {
  content: "@earth_online";

  display: block;

  color: #73818a;

  font-size: 13px;
  font-weight: 400;
  line-height: 1.3;
}


/* ==========================================================
   5. 论坛分区标签
   ========================================================== */

.xt-badge {
  display: inline-flex !important;
  align-items: center !important;

  width: auto !important;

  margin: 8px 20px 3px !important;
  padding: 5px 9px !important;

  color: #34758f !important;
  background: #edf7fb !important;

  border: 1px solid #d5ebf3 !important;
  border-radius: 6px !important;

  box-shadow: none !important;

  font-size: 12px !important;
  font-weight: 650 !important;
  line-height: 1.3 !important;
}

.xt-badge-value,
.xt-badge-suffix {
  color: inherit !important;
  font-size: inherit !important;
}


/* ==========================================================
   6. 主帖标题
   ========================================================== */

.xt-text-forumTitle {
  display: block !important;

  width: 100%;

  margin: 0 !important;
  padding: 13px 20px 0 !important;

  box-sizing: border-box;

  color: #111111 !important;
  background: transparent !important;

  border: 0 !important;
  border-radius: 0 !important;

  box-shadow: none !important;

  font-size: 22px !important;
  font-weight: 780 !important;
  line-height: 1.45 !important;
  letter-spacing: -0.3px !important;

  white-space: pre-wrap;
  overflow-wrap: anywhere;
}


/* ==========================================================
   7. 主帖正文
   ========================================================== */

.xt-text-forumPost {
  display: block !important;

  width: 100%;

  margin: 0 !important;
  padding: 14px 20px 10px !important;

  box-sizing: border-box;

  color: #202020 !important;
  background: transparent !important;

  border: 0 !important;
  border-radius: 0 !important;

  box-shadow: none !important;

  font-size: 17px !important;
  font-weight: 400 !important;
  line-height: 1.72 !important;
  letter-spacing: 0 !important;

  white-space: pre-wrap;
  overflow-wrap: anywhere;
}


/* ==========================================================
   8. 附件提示
   ========================================================== */

.xt-text-attachment {
  display: block !important;

  width: calc(100% - 40px);

  margin: 8px 20px 12px !important;
  padding: 13px 14px !important;

  box-sizing: border-box;

  color: #44515a !important;
  background: #f6f8f9 !important;

  border: 1px solid #e6eaed !important;
  border-radius: 10px !important;

  box-shadow: none !important;

  font-size: 14px !important;
  font-weight: 450 !important;
  line-height: 1.5 !important;
  text-align: left !important;
}


/* ==========================================================
   9. 发布时间和主帖操作栏
   ========================================================== */

.xt-text-postTime {
  display: block !important;

  width: 100%;

  margin: 0 !important;
  padding: 5px 20px 16px !important;

  box-sizing: border-box;

  color: #71808a !important;
  background: transparent !important;

  border: 0 !important;
  border-radius: 0 !important;

  box-shadow: none !important;

  font-size: 13px !important;
  font-weight: 400 !important;
  line-height: 1.5 !important;
}

.xt-text-postTime::after {
  content: "◯　　　　⇄　　　　♡　　　　⌯";

  display: block;

  margin-top: 14px;
  padding-top: 13px;

  color: #687b87;

  border-top: 1px solid #e6e9eb;

  font-family: Arial, sans-serif;
  font-size: 22px;
  line-height: 1;
  letter-spacing: 0;
  text-align: center;
}


/* ==========================================================
   10. 回复区分隔
   ========================================================== */

.xt-divider {
  position: relative;

  display: block !important;

  width: 100%;
  height: auto !important;

  margin: 0 !important;
  padding: 15px 20px 12px !important;

  box-sizing: border-box;

  background: #ffffff !important;

  border: 0 !important;
  border-top: 8px solid #f3f5f6 !important;
  border-bottom: 1px solid #e5e9ec !important;
}

.xt-divider::after {
  content: "回复";

  display: block;

  color: #171717;

  font-size: 16px;
  font-weight: 700;
  line-height: 1.4;
}


/* ==========================================================
   11. 七条回复卡片
   ========================================================== */

.xt-card {
  position: relative;

  display: block !important;

  width: 100%;

  margin: 0 !important;
  padding: 16px 20px 14px 70px !important;

  box-sizing: border-box;

  background: #ffffff !important;

  border: 0 !important;
  border-bottom: 1px solid #e5e9ec !important;
  border-radius: 0 !important;

  box-shadow: none !important;
}


/* 回复头像占位 */

.xt-card::before {
  content: "";

  position: absolute;
  top: 17px;
  left: 20px;

  width: 38px;
  height: 38px;

  background:
    linear-gradient(
      145deg,
      #dce8ed,
      #bccdd5
    );

  border-radius: 50%;
}


/* 回复菜单 */

.xt-card::after {
  content: "•••";

  position: absolute;
  top: 15px;
  right: 17px;

  color: #89969e;

  font-family: Arial, sans-serif;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 2px;
}


/* ==========================================================
   12. 所有网友昵称
   ========================================================== */

.xt-text-n1,
.xt-text-n2,
.xt-text-n3,
.xt-text-n4,
.xt-text-n5,
.xt-text-n6,
.xt-text-n7 {
  display: block !important;

  width: calc(100% - 30px);

  margin: 0 0 7px !important;
  padding: 0 !important;

  color: #202020 !important;
  background: transparent !important;

  border: 0 !important;
  border-radius: 0 !important;

  box-shadow: none !important;

  font-size: 15px !important;
  font-weight: 720 !important;
  line-height: 1.4 !important;

  white-space: pre-wrap;
  overflow-wrap: anywhere;
}


/* char本人出现的楼层 */

.xt-text-n4,
.xt-text-n7 {
  display: inline-block !important;

  width: auto !important;

  padding: 2px 7px !important;

  color: #ad5879 !important;
  background: #fde5ee !important;

  border-radius: 5px !important;
}

.xt-text-n4::after,
.xt-text-n7::after {
  content: "  楼主";

  color: #c17290;

  font-size: 11px;
  font-weight: 600;
}


/* ==========================================================
   13. 所有回复正文
   ========================================================== */

.xt-text-r1,
.xt-text-r2,
.xt-text-r3,
.xt-text-r4,
.xt-text-r5,
.xt-text-r6,
.xt-text-r7 {
  display: block !important;

  width: 100%;

  margin: 0 !important;
  padding: 0 !important;

  color: #272727 !important;
  background: transparent !important;

  border: 0 !important;
  border-radius: 0 !important;

  box-shadow: none !important;

  font-size: 15px !important;
  font-weight: 400 !important;
  line-height: 1.65 !important;

  white-space: pre-wrap;
  overflow-wrap: anywhere;
}

.xt-text-r1::after,
.xt-text-r2::after,
.xt-text-r3::after,
.xt-text-r4::after,
.xt-text-r5::after,
.xt-text-r6::after,
.xt-text-r7::after {
  content: "◯　　⇄　　♡";

  display: block;

  margin-top: 11px;

  color: #89969e;

  font-family: Arial, sans-serif;
  font-size: 15px;
  line-height: 1;
  letter-spacing: 1px;
}


/* ==========================================================
   14. char回复的轻微区别
   ========================================================== */

.xt-card:has(.xt-text-n4),
.xt-card:has(.xt-text-n7) {
  background:
    linear-gradient(
      90deg,
      rgba(253, 229, 238, 0.22),
      transparent 55%
    ) !important;
}

.xt-card:has(.xt-text-n4)::before,
.xt-card:has(.xt-text-n7)::before {
  background:
    linear-gradient(
      145deg,
      #f3bfd1,
      #d88fac
    );
}


/* ==========================================================
   15. 隐秘想法
   ========================================================== */

.xt-text-secretThought {
  display: block !important;

  width: calc(100% - 36px);

  margin: 16px 18px !important;
  padding: 13px 14px !important;

  box-sizing: border-box;

  color: #765663 !important;
  background: #fff5f8 !important;

  border: 1px dashed #ecc8d6 !important;
  border-radius: 10px !important;

  box-shadow: none !important;

  font-size: 13px !important;
  font-weight: 400 !important;
  line-height: 1.65 !important;

  white-space: pre-wrap;
  overflow-wrap: anywhere;
}

.xt-text-secretThought::before {
  content: "仅楼主可见";

  display: block;

  margin-bottom: 6px;

  color: #bd718e;

  font-size: 11px;
  font-weight: 700;
  letter-spacing: 1px;
}


/* ==========================================================
   16. 底部
   ========================================================== */

.xt-footer {
  display: block !important;

  width: 100%;

  margin: 0 !important;
  padding: 15px 20px 18px !important;

  box-sizing: border-box;

  color: #a5afb5 !important;
  background: #f8f9fa !important;

  border: 0 !important;
  border-top: 1px solid #eceff1 !important;
  border-radius: 0 !important;

  box-shadow: none !important;

  font-size: 10px !important;
  font-weight: 400 !important;
  line-height: 1.5 !important;
  letter-spacing: 1px !important;
  text-align: center !important;
}


/* ==========================================================
   17. 滚动条
   ========================================================== */

.xt-root::-webkit-scrollbar {
  width: 4px;
}

.xt-root::-webkit-scrollbar-track {
  background: transparent;
}

.xt-root::-webkit-scrollbar-thumb {
  background: #d7dce0;
  border-radius: 10px;
}


/* ==========================================================
   18. 点击反馈
   ========================================================== */

.xt-card {
  transition:
    background-color 0.18s ease,
    transform 0.18s ease;
}

.xt-card:active {
  background: #f8f9fa !important;
  transform: scale(0.996);
}


/* ==========================================================
   19. 手机适配
   ========================================================== */

@media (max-width: 390px) {
  .xt-root {
    height: 78vh !important;
    min-height: 500px;
    border-radius: 15px !important;
  }

  .xt-header {
    padding:
      16px
      17px
      9px !important;
  }

  .xt-avatar {
    width: 50px !important;
    height: 50px !important;
    min-width: 50px !important;
    flex-basis: 50px !important;
  }

  .xt-badge {
    margin-left: 17px !important;
    margin-right: 17px !important;
  }

  .xt-text-forumTitle {
    padding-left: 17px !important;
    padding-right: 17px !important;

    font-size: 20px !important;
  }

  .xt-text-forumPost {
    padding-left: 17px !important;
    padding-right: 17px !important;

    font-size: 16px !important;
  }

  .xt-text-attachment {
    width: calc(100% - 34px);

    margin-left: 17px !important;
    margin-right: 17px !important;
  }

  .xt-text-postTime {
    padding-left: 17px !important;
    padding-right: 17px !important;
  }

  .xt-divider {
    padding-left: 17px !important;
    padding-right: 17px !important;
  }

  .xt-card {
    padding:
      15px
      17px
      13px
      64px !important;
  }

  .xt-card::before {
    left: 17px;

    width: 36px;
    height: 36px;
  }

  .xt-text-r1,
  .xt-text-r2,
  .xt-text-r3,
  .xt-text-r4,
  .xt-text-r5,
  .xt-text-r6,
  .xt-text-r7 {
    font-size: 14px !important;
  }
}

