/* ==========================================================
   16. char本人回复
   ========================================================== */

.xt-text-rantName5,
.xt-text-moonName5,
.xt-text-draftName5 {
  color: #ae5c7b !important;
  background:
    linear-gradient(
      90deg,
      rgba(253, 229, 238, 0.32),
      #ffffff 58%
    ) !important;
}

.xt-text-rantName5::after,
.xt-text-moonName5::after,
.xt-text-draftName5::after {
  content: "楼主";

